local KiteMaker = {}
local PRODUCTS = {
    paper_kite = { name = "Papirni zmaj", paperCost = 2, woodCost = 1, stringCost = 1, time = 1, cost = 10, flightQuality = 40, happiness = 2, description = "Papirni zmaj za otroke." },
    silk_kite = { name = "Svileni zmaj", silkCost = 1, woodCost = 1, stringCost = 1, time = 2, cost = 28, flightQuality = 55, prestige = 1, happiness = 3, description = "Svileni zmaj za trgovce." },
    painted_kite = { name = "Poslikani zmaj", silkCost = 1, paintCost = 1, woodCost = 1, stringCost = 1, time = 4, cost = 65, flightQuality = 70, prestige = 3, happiness = 4, description = "Poslikani zmaj z motivi." },
    silver_tailed_kite = { name = "Srebrnorepni zmaj", silkCost = 1, silverCost = 1, paintCost = 1, woodCost = 1, stringCost = 1, time = 6, cost = 150, flightQuality = 82, prestige = 7, happiness = 5, description = "Zmaj s srebrnim repom za plemiče." },
    gold_streamer_kite = { name = "Zlatoropni zmaj", silkCost = 2, goldCost = 1, silverCost = 1, paintCost = 1, woodCost = 1, stringCost = 1, time = 9, cost = 340, flightQuality = 92, prestige = 14, happiness = 7, description = "Zlatoropni zmaj za visoke plemiče." },
    royal_grand_kite = { name = "Kraljevski veliki zmaj", silkCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, paintCost = 2, woodCost = 1, stringCost = 1, time = 14, cost = 1200, flightQuality = 100, prestige = 35, happiness = 12, description = "Veliki kraljevski zmaj z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Zmajarica delavnica", cost = { gold = 240, wood = 120, stone = 150 }, upkeep = 5, qualityBonus = 5 },
    silk_room = { name = "Svilničnica", cost = { gold = 800, wood = 220, stone = 300, silk = 8 }, upkeep = 20, qualityBonus = 18 },
    painting_room = { name = "Slikalnica", cost = { gold = 2000, wood = 300, stone = 500, silver = 25, paint = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_kite_atelier = { name = "Kraljevski atelje zmajev", cost = { gold = 8200, wood = 500, stone = 900, gold = 60, jewel = 20 }, upkeep = 165, qualityBonus = 55, prestigeBonus = 40 },
}
KiteMaker.paperStock = 18; KiteMaker.silkStock = 10; KiteMaker.woodStock = 14; KiteMaker.stringStock = 14; KiteMaker.paintStock = 12; KiteMaker.silverStock = 8; KiteMaker.goldStock = 6; KiteMaker.jewelStock = 6; KiteMaker.pearlStock = 4
KiteMaker.productStock = {}; KiteMaker.buildings = {}; KiteMaker.maker = nil; KiteMaker.activeMaking = {}; KiteMaker.totalProducts = 0; KiteMaker.dayTimer = 0
function KiteMaker.init() KiteMaker.paperStock=18; KiteMaker.silkStock=10; KiteMaker.woodStock=14; KiteMaker.stringStock=14; KiteMaker.paintStock=12; KiteMaker.silverStock=8; KiteMaker.goldStock=6; KiteMaker.jewelStock=6; KiteMaker.pearlStock=4; KiteMaker.productStock={}; KiteMaker.buildings={}; KiteMaker.maker=nil; KiteMaker.activeMaking={}; KiteMaker.totalProducts=0; KiteMaker.dayTimer=0; print("[KiteMaker] Royal Kite Maker System initialized (6 products, 4 buildings)") end
function KiteMaker.hireMaker(n,s) s=s or math.random(45,85); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; KiteMaker.maker={name=n or ("Zmajar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zmajar najet: %s (spretnost: %d)",KiteMaker.maker.name,s),"success") end; return true end
function KiteMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function KiteMaker.build(id) local ok,e=KiteMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(KiteMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function KiteMaker.getQualityBonus() local b=0; for _,bd in ipairs(KiteMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function KiteMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.paperCost and KiteMaker.paperStock<(d.paperCost or 0) then return false,"Premalo papirja" end; if d.silkCost and KiteMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.woodCost and KiteMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.stringCost and KiteMaker.stringStock<(d.stringCost or 0) then return false,"Premalo vrvi" end; if d.paintCost and KiteMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and KiteMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and KiteMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and KiteMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and KiteMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #KiteMaker.buildings==0 then return false,"Potrebna delavnica" end; if not KiteMaker.maker then return false,"Potreben zmajar" end; return true end
function KiteMaker.make(pt,qty) qty=qty or 1; local ok,e=KiteMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.paperCost then KiteMaker.paperStock=KiteMaker.paperStock-d.paperCost*qty end; if d.silkCost then KiteMaker.silkStock=KiteMaker.silkStock-d.silkCost*qty end; if d.woodCost then KiteMaker.woodStock=KiteMaker.woodStock-d.woodCost*qty end; if d.stringCost then KiteMaker.stringStock=KiteMaker.stringStock-d.stringCost*qty end; if d.paintCost then KiteMaker.paintStock=KiteMaker.paintStock-d.paintCost*qty end; if d.silverCost then KiteMaker.silverStock=KiteMaker.silverStock-d.silverCost*qty end; if d.goldCost then KiteMaker.goldStock=KiteMaker.goldStock-d.goldCost*qty end; if d.jewelCost then KiteMaker.jewelStock=KiteMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then KiteMaker.pearlStock=KiteMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if KiteMaker.maker then t=math.max(1,t-math.floor(KiteMaker.maker.skill/12)) end; table.insert(KiteMaker.activeMaking,{id="kite_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flightQuality=d.flightQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function KiteMaker.completeMaking(m) local q=1.0+(KiteMaker.getQualityBonus()/100); if KiteMaker.maker then q=q+(KiteMaker.maker.skill/180) end; q=math.min(2.0,q); KiteMaker.productStock[m.productType]=(KiteMaker.productStock[m.productType] or 0)+m.quantity; KiteMaker.totalProducts=KiteMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if KiteMaker.maker then KiteMaker.maker.itemsMade=KiteMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then KiteMaker.maker.skill=math.min(100,KiteMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zmaj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"kite.completed",{productName=m.productName,flightQuality=m.flightQuality,happiness=m.happiness}) end end
function KiteMaker.update(dt) if not _G.state then return end; KiteMaker.dayTimer=KiteMaker.dayTimer+dt; if KiteMaker.dayTimer>=30 then KiteMaker.dayTimer=0; for i=#KiteMaker.activeMaking,1,-1 do local m=KiteMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then KiteMaker.completeMaking(m); table.remove(KiteMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(KiteMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if KiteMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function KiteMaker.getStats() return {paperStock=KiteMaker.paperStock,silkStock=KiteMaker.silkStock,woodStock=KiteMaker.woodStock,stringStock=KiteMaker.stringStock,paintStock=KiteMaker.paintStock,silverStock=KiteMaker.silverStock,goldStock=KiteMaker.goldStock,jewelStock=KiteMaker.jewelStock,pearlStock=KiteMaker.pearlStock,productStock=KiteMaker.productStock,numBuildings=#KiteMaker.buildings,hasMaker=KiteMaker.maker~=nil,makerName=KiteMaker.maker and KiteMaker.maker.name or "—",makerSkill=KiteMaker.maker and KiteMaker.maker.skill or 0,activeMaking=#KiteMaker.activeMaking,totalProducts=KiteMaker.totalProducts} end
return KiteMaker
